import { createEffect, createUniqueId, onCleanup, onMount, splitProps, type JSX } from 'solid-js';
import { getSwitchState, switchStyleKeys } from '../lib/core';
import type { SwitchBaseProps } from '../lib/core';
import { HIDDEN_FORM_CONTROL_PROPS, createControllableSignal, createFormResetBinding, invokeEventHandler, setInitialNativeChecked, setNativeChecked } from '../lib/utils';
import styles from './switch.module.scss';

export interface SwitchProps extends Omit<JSX.ButtonHTMLAttributes<HTMLButtonElement>, 'defaultChecked' | 'name' | 'onChange' | 'required' | 'value'>, SwitchBaseProps {
	checked?: boolean;
	defaultChecked?: boolean;
	onCheckedChange?: (checked: boolean) => void;
	name?: string;
	value?: string;
	form?: string;
	required?: boolean;
}

/** SolidJS Switch：使用隐藏原生 checkbox 提供表单语义。 */
export function Switch(props: SwitchProps) {
	const [local, rest] = splitProps(props, [
		'size',
		'checked',
		'defaultChecked',
		'onCheckedChange',
		'name',
		'value',
		'form',
		'required',
		'disabled',
		'class',
		'onClick',
		'children',
		'type',
	]);
	const initialChecked = local.defaultChecked ?? false;
	const [checked, setChecked, resetChecked] = createControllableSignal({
		value: () => local.checked,
		defaultValue: () => initialChecked,
		onChange: (next) => local.onCheckedChange?.(next),
	});
	const controlId = `tile-solid-switch-${createUniqueId()}`;
	let control: HTMLInputElement | undefined;

	const syncControl = () => {
		if (control) setNativeChecked(control, checked());
	};

	const resetBinding = createFormResetBinding(() => {
		resetChecked();
		queueMicrotask(syncControl);
	});
	const bindReset = () => {
		resetBinding.bind(control);
	};

	onMount(() => {
		createEffect(syncControl);
		createEffect(() => {
			const form = local.form;
			bindReset();
			return form;
		});
		setInitialNativeChecked(control, initialChecked);
		onCleanup(resetBinding.cleanup);
	});

	return (
		<>
			<button
				{...rest}
				type={local.type ?? 'button'}
				role="switch"
				aria-checked={checked()}
				data-state={getSwitchState(checked())}
				data-size={local.size ?? 'default'}
				disabled={local.disabled}
				class={`${styles[switchStyleKeys.root]} ${local.class ?? ''}`}
				onClick={(event) => {
					invokeEventHandler(local.onClick, event);
					if (!event.defaultPrevented) setChecked(!checked());
				}}>
				<span class={styles[switchStyleKeys.thumb]} />
				{local.children}
			</button>
			<input
				{...HIDDEN_FORM_CONTROL_PROPS}
				ref={(element) => {
					control = element;
					bindReset();
				}}
				id={controlId}
				type="checkbox"
				name={local.name}
				value={local.value ?? 'on'}
				form={local.form}
				required={local.required}
				disabled={local.disabled}
			/>
		</>
	);
}

export default Switch;

@use '../../../styles/variables/colors' as *;

.root {
	display: inline-flex;
	flex-shrink: 0;
	align-items: center;
	border-radius: var(--tile-switch-radius, #{$radius-full});
	border: var(--tile-switch-border-width, 1px) solid transparent;
	box-shadow: var(--tile-switch-shadow, #{$shadow-sm});
	transition: background-color $transition-fast;
	outline: none;

	&:focus-visible {
		border-color: $ring;
	}

	&:disabled {
		cursor: not-allowed;
		opacity: 0.5;
	}

	&[data-size='default'] {
		width: var(--tile-switch-width, 2rem);
		height: var(--tile-switch-height, 1.15rem);
	}

	&[data-size='sm'] {
		width: var(--tile-switch-sm-width, 1.5rem);
		height: var(--tile-switch-sm-height, 0.875rem);
	}

	&[data-state='checked'] {
		background-color: var(--tile-switch-checked-background, #{$primary});
		color: $primary-foreground;
		box-shadow: var(--tile-switch-checked-shadow, #{$shadow-sm});
	}

	&[data-state='unchecked'] {
		background-color: var(--tile-switch-background, #{$input});
		color: $foreground;
	}

	&:focus-visible {
		box-shadow: var(--tile-switch-focus-shadow, 0 0 0 1px #{$ring}, 0 0 0 3px color-mix(in srgb, #{$ring} 50%, transparent));
		outline: var(--tile-switch-focus-outline, none);
		outline-offset: var(--tile-switch-focus-offset, 0px);
	}
}

.thumb {
	pointer-events: none;
	display: block;
	border-radius: var(--tile-switch-radius, #{$radius-full});
	background-color: var(--tile-switch-thumb-background, #{$background});
	box-shadow: var(--tile-switch-thumb-shadow, none);
	transition: transform $transition-normal;

	[data-size='default'] & {
		width: var(--tile-switch-thumb-size, 1rem);
		height: var(--tile-switch-thumb-size, 1rem);
	}

	[data-size='sm'] & {
		width: var(--tile-switch-sm-thumb-size, 0.75rem);
		height: var(--tile-switch-sm-thumb-size, 0.75rem);
	}

	[data-state='checked'] & {
		transform: translateX(var(--tile-switch-thumb-travel, calc(100% - 2px)));
		background-color: var(--tile-switch-checked-thumb-background, #{$background});
	}

	[data-state='unchecked'] & {
		transform: translateX(0);
	}
}

// Optional corner styling falls back to round corners in unsupported browsers.
@supports (corner-shape: squircle) {
	.root,
	.thumb {
		corner-shape: var(--tile-switch-corner-shape, round);
		border-radius: var(--tile-switch-squircle-radius, #{$radius-full});
	}
}
